def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the full straight separator between two same-sized panels.
    sep = None
    orientation = None
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            sep, orientation = c, 'v'
            break
    if sep is None:
        for r in range(h):
            if len(set(grid[r])) == 1:
                sep, orientation = r, 'h'
                break
    if sep is None:
        raise ValueError('no uniform separator')
    if orientation == 'v':
        a = [row[:sep] for row in grid]
        b = [row[sep+1:] for row in grid]
    else:
        a, b = grid[:sep], grid[sep+1:]
    # First panel contains the pattern; second panel specifies which positions
    # are excluded. Output uses the second panel's background and color 3 marks.
    from collections import Counter
    bg_a = Counter(x for row in a for x in row).most_common(1)[0][0]
    bg_b = Counter(x for row in b for x in row).most_common(1)[0][0]
    return [[3 if a[r][c] != bg_a and b[r][c] == bg_b else bg_b
             for c in range(len(a[0]))] for r in range(len(a))]

